package ru.neverland.townyjustice;
import java.util.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import com.palmergames.bukkit.towny.TownyAPI;
import ru.neverland.core.MenuStyle;
public final class JusticeCommand implements CommandExecutor,TabCompleter {
    private final NeverLandTownyJustice plugin;private final JusticeDossiersMenu dossiersMenu;private final JusticeService service;private final JusticeMenu menu;
    public JusticeCommand(NeverLandTownyJustice p,JusticeService s,JusticeMenu m){plugin=p;service=s;menu=m;dossiersMenu=new JusticeDossiersMenu(p,s);}
    private static void length(String[] args,int count,String syntax){if(args.length!=count)throw new IllegalArgumentException(syntax);}
    private boolean manager(Player p){try{return service.manager(p,service.ownTown(p).getUUID());}catch(IllegalArgumentException e){return false;}}
    private UUID caseId(Player p,String key){var matches=service.repository().state().cases().values().stream().filter(c->service.readable(p,c)&&key.length()>=8&&c.id().toString().startsWith(key.toLowerCase(Locale.ROOT))).map(JusticeCase::id).toList();if(matches.size()!=1)throw new IllegalArgumentException("Укажите полный ID дела или однозначные первые 8 символов");return matches.get(0);}
    private UUID dossierId(Player p,String key){var matches=service.dossiers().cases(p).stream().filter(c->key.length()>=8&&c.id().toString().startsWith(key.toLowerCase(Locale.ROOT))).map(JusticeCase::id).toList();if(matches.size()!=1)throw new IllegalArgumentException("Укажите полный ID доступного дела или однозначные первые 8 символов");return matches.get(0);}
    private void receipt(Player p,java.util.concurrent.CompletionStage<String> stage){say(p,"&7Сохраняем материалы дела…");stage.whenComplete((message,error)->{if(!plugin.isEnabled()||ru.neverland.core.SuiteState.frozen(plugin.getName()))return;ru.neverland.core.SuiteScheduler.reply(plugin,p,()->{if(error==null)say(p,"&a"+message);else{var cause=error;while(cause.getCause()!=null)cause=cause.getCause();say(p,"&cЗапись не подтверждена: "+cause.getMessage());}});});}
    private UUID resident(String name){var r=TownyAPI.getInstance().getResident(name);if(r==null)throw new IllegalArgumentException("Игрок не найден в Towny");return r.getUUID();}
    static void say(CommandSender s,String text){s.sendMessage(MenuStyle.decode(text));}
    @Override public boolean onCommand(CommandSender s,Command command,String label,String[] args){ try (var suiteGuard1 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJustice")){return true;}try{
        String action=args.length==0?"menu":args[0].toLowerCase(Locale.ROOT);
        if(Set.of("reload","payments","resolve").contains(action)){
            if(!s.hasPermission("neverlandtownyjustice.admin"))throw new IllegalArgumentException("Недостаточно прав");
            if(action.equals("reload")){length(args,1,"/justice reload");plugin.reloadJustice();say(s,"&aНастройки суда обновлены.");}
            else if(action.equals("payments")){length(args,1,"/justice payments");say(s,"&eНезавершённые платежи — ID, назначение, сумма, состояние:");service.repository().state().payments().values().stream().filter(p->p.step()!=JusticePayment.Step.COMPLETE&&p.step()!=JusticePayment.Step.CANCELLED).forEach(p->say(s,"&f"+p.id()+" | "+p.kind()+" | "+JusticeMenu.money(p.amount())+" | "+p.step()+" | город "+p.town()+" | игрок "+p.resident()));say(s,"&7Сверьте журнал банка по [justice:ID] перед resolve.");}
            else{length(args,3,"/justice resolve <ID платежа> <решение после сверки банка>");service.resolve(UUID.fromString(args[1]),args[2]);say(s,"&aРезультат сверки сохранён.");}return true;
        }
        if(!s.hasPermission("neverlandtownyjustice.use"))throw new IllegalArgumentException("Недостаточно прав");
        if(action.equals("help")){say(s,"&eГородской суд и розыск");say(s,"&b/justice fines &f— мои штрафы и оплата");say(s,"&b/justice dossier [ID] &f— материалы, апелляции и история решений");say(s,"&b/justice wanted &f— действующий розыск и награды");say(s,"&b/justice case <ID> &f— дело; &bpay <ID> &f— оплатить свой штраф");say(s,"&b/justice capture <ID> &f— задержать рядом, в городе-инициаторе");if(s instanceof Player p&&manager(p)){say(s,"&b/justice fine <игрок> <сумма> <причина> &f— штраф");say(s,"&b/justice warrant <игрок> <награда> <часы> <причина> &f— розыск");say(s,"&b/justice cancel <ID> &f— отмена; &brelease <ID> &f— освобождение");say(s,"&b/justice prison <create|bind|unbind> <имя> &f— тюрьма");say(s,"&b/justice cases &f— дела города");}return true;}
        if(!(s instanceof Player p))throw new IllegalArgumentException("Команда доступна в игре");
        switch(action){
            case "dossier"->{if(args.length>2)throw new IllegalArgumentException("/justice dossier [ID дела]");dossiersMenu.open(p,args.length==2?dossierId(p,args[1]):null,"detail",0);}
            case "evidence"->{if(args.length<4)throw new IllegalArgumentException("/justice evidence <ID дела> note <пояснение> или incident <UUID происшествия>");UUID id=dossierId(p,args[1]);if(args[2].equals("note"))receipt(p,service.dossiers().note(p,id,String.join(" ",Arrays.copyOfRange(args,3,args.length))));else if(args[2].equals("incident")&&args.length==4)receipt(p,service.dossiers().incident(p,id,UUID.fromString(args[3])));else throw new IllegalArgumentException("Укажите note <текст> или incident <UUID>");}
            case "appeal"->{if(args.length<3)throw new IllegalArgumentException("/justice appeal <ID дела> <обоснование>");receipt(p,service.dossiers().appeal(p,dossierId(p,args[1]),String.join(" ",Arrays.copyOfRange(args,2,args.length))));}
            case "assign"->{length(args,3,"/justice assign <ID дела> <житель>");receipt(p,service.dossiers().assign(p,dossierId(p,args[1]),resident(args[2])));}
            case "review"->{if(args.length<4||!Set.of("uphold","reconsider").contains(args[2]))throw new IllegalArgumentException("/justice review <ID дела> uphold|reconsider <обоснование>");receipt(p,service.dossiers().decide(p,dossierId(p,args[1]),args[2].equals("uphold")?JusticeDossiers.Outcome.UPHELD:JusticeDossiers.Outcome.RECONSIDER,String.join(" ",Arrays.copyOfRange(args,3,args.length))));}
            case "menu","fines","wanted","cases"->{length(args,args.length==0?0:1,"/justice "+action);menu.open(p,action,0,MenuStyle.previousMenu(p));}
            case "case"->{length(args,2,"/justice case <ID>");menu.detail(p,caseId(p,args[1]),MenuStyle.previousMenu(p));}
            case "fine","warrant"->{int start=action.equals("fine")?3:4;if(args.length<=start)throw new IllegalArgumentException(action.equals("fine")?"/justice fine <игрок> <сумма> <причина>":"/justice warrant <игрок> <награда> <часы> <причина>");UUID id=service.issue(p,action.equals("fine")?JusticeCase.Kind.FINE:JusticeCase.Kind.WARRANT,resident(args[1]),JusticeSettings.cents(args[2]),action.equals("fine")?0:Integer.parseInt(args[3]),String.join(" ",Arrays.copyOfRange(args,start,args.length)));say(s,"&aДело сохранено: &f"+id);menu.detail(p,id,MenuStyle.previousMenu(p));}
            case "pay","cancel","capture","release"->{length(args,2,"/justice "+action+" <ID>");UUID id=caseId(p,args[1]);switch(action){case "pay"->service.pay(p,id);case "cancel"->service.cancel(p,id);case "capture"->service.capture(p,id);case "release"->service.release(p,id);}say(s,"&eСостояние дела: &f"+JusticeMenu.phase(service.get(id).phase()));}
            case "prison"->{length(args,3,"/justice prison <create|bind|unbind> <имя>");switch(args[1]){case "create","bind"->{UUID id=service.createPrison(p,args[2],args[1].equals("bind"));say(s,"&aТюрьма подключена: &f"+id);}case "unbind"->{service.unbind(p,args[2]);say(s,"&aТюрьма отключена от суда. Участок Towny сохранён.");}default->throw new IllegalArgumentException("/justice prison <create|bind|unbind> <имя>");}}
            default->throw new IllegalArgumentException("Справка: /justice help");
        }
    }catch(Exception ex){say(s,"&c"+(ex instanceof IllegalArgumentException?ex.getMessage():"Операция ожидает проверки; откройте дело или обратитесь к администратору"));if(!(ex instanceof IllegalArgumentException))plugin.getLogger().log(java.util.logging.Level.WARNING,"Команда суда",ex);}return true;} }
    @Override public List<String> onTabComplete(CommandSender s,Command command,String alias,String[] args){ try (var suiteGuard2 = ru.neverland.core.SuiteState.guard()) {var choices=new ArrayList<String>();if(args.length==1){if(s.hasPermission("neverlandtownyjustice.use")){choices.addAll(List.of("menu","fines","wanted","case","pay","help","dossier","evidence","appeal"));if(s.hasPermission("neverlandtownyjustice.capture"))choices.add("capture");if(s instanceof Player p&&manager(p))choices.addAll(List.of("cases","fine","warrant","cancel","release","prison","assign","review"));}if(s.hasPermission("neverlandtownyjustice.admin"))choices.addAll(List.of("reload","payments","resolve"));}
        else if(args.length==2&&s instanceof Player p&&s.hasPermission("neverlandtownyjustice.use")){if(Set.of("dossier","evidence","appeal","assign","review").contains(args[0]))service.dossiers().cases(p).forEach(c->choices.add(c.id().toString()));if(Set.of("case","pay","capture","cancel","release").contains(args[0]))service.repository().state().cases().values().stream().filter(c->service.readable(p,c)).forEach(c->choices.add(c.id().toString()));if(Set.of("fine","warrant").contains(args[0])&&manager(p))TownyAPI.getInstance().getResidents().forEach(r->choices.add(r.getName()));if(args[0].equals("prison")&&manager(p))choices.addAll(List.of("create","bind","unbind"));}
        else if(args.length==3&&args[0].equals("evidence"))choices.addAll(List.of("note","incident"));else if(args.length==3&&args[0].equals("review"))choices.addAll(List.of("uphold","reconsider"));else if(args.length==3&&args[0].equals("resolve")&&s.hasPermission("neverlandtownyjustice.admin"))choices.addAll(List.of("debit-applied","debit-not-applied","credit-applied","credit-not-applied"));String prefix=args.length==0?"":args[args.length-1].toLowerCase(Locale.ROOT);return choices.stream().filter(v->v.toLowerCase(Locale.ROOT).startsWith(prefix)).sorted().toList();} }
}
